import java.util.*;

public class OrderProcessor {
    public void processOrders(List<Order> orders) {
        // 1. For-each loop - clean, read-only access
        for (Order order : orders) {
            System.out.println(order.id());
        }

        // 2. Iterator - allows safe removal during iteration
        Iterator<Order> iterator = orders.iterator();
        while (iterator.hasNext()) {
            Order order = iterator.next();
            if (order.amount() < 10) {
                iterator.remove(); // safe removal
            }
        }

        // 3. ListIterator - bidirectional traversal
        ListIterator<Order> listIter = orders.listIterator(orders.size());
        while (listIter.hasPrevious()) {
            Order order = listIter.previous(); // backward iteration
            System.out.println(order.item());
        }

        // 4. forEach with lambda - functional style
        orders.forEach(order -> System.out.println(order.customer()));
    }
}

record Order(Long id, String item, String customer, double amount) {}

